import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const m=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/quick-start.md","filePath":"zh/guides/quick-start.md","lastUpdated":1790952322000}'),s={name:"zh/guides/quick-start.md"};function n(l,t,i,d,h,p){return e(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>一份从零开始的完整教程：安装应用、登录、创建第一个 Bot、交给它真实工作，并在聊天平台上找到它。大约需要十五分钟。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>一台 macOS、Windows 或 Linux 电脑。</li><li>一个 <a href="https://app.memoh.net" target="_blank" rel="noreferrer">Memoh Cloud</a> 账号——登录时可以直接注册。</li></ul><p>就这些。Memoh Cloud 内置了托管模型（DeepSeek、Kimi、GPT、Claude 等），上手不需要任何 API Key。</p><h2 id="第-1-步-安装-memoh" tabindex="-1">第 1 步：安装 Memoh <a class="header-anchor" href="#第-1-步-安装-memoh" aria-label="Permalink to &quot;第 1 步：安装 Memoh&quot;">​</a></h2><p>从 <a href="https://memoh.ai/desktop" target="_blank" rel="noreferrer">下载页</a> 下载对应平台的安装包——macOS（DMG）、Windows（安装程序）或 Linux（AppImage/deb/rpm）——然后打开它。</p><h2 id="第-2-步-登录" tabindex="-1">第 2 步：登录 <a class="header-anchor" href="#第-2-步-登录" aria-label="Permalink to &quot;第 2 步：登录&quot;">​</a></h2><p>在连接页选择 <strong>Memoh Cloud</strong> 并登录，没有账号就先注册一个。</p><h2 id="第-3-步-创建第一个-bot" tabindex="-1">第 3 步：创建第一个 Bot <a class="header-anchor" href="#第-3-步-创建第一个-bot" aria-label="Permalink to &quot;第 3 步：创建第一个 Bot&quot;">​</a></h2><p>进入 <strong>Bot → 新建 Bot</strong>，填写名称与显示名，然后在 <strong>通用</strong> 标签页选择对话模型。托管模型开箱即用。</p><p>接下来写它的指令。这一步最关键，也最容易出错——通常是写得太笼统。把一件事说清楚：</p><blockquote><p><strong>名称：</strong> Digest</p><p><strong>角色：</strong> 每周阅读摘要</p><p><strong>指令：</strong> 收集我这一周发给你的文章。每周五整理成一份摘要，按主题分组：每篇一句话概括并附原始链接，最后加一节&quot;值得再读&quot;。原始链接保持不变。任何内容都不要公开发布。</p></blockquote><p>职责单一的 Bot 能积累的有效上下文，远多于什么都干的 Bot。当工作确实分成不同角色时，请新建一个 Bot，而不是把这个越堆越重——每个 Bot 都有独立的工作区、记忆和配置。逐个标签页的说明见 <a href="./working-with-bots.html">Bot</a>。</p><p>点击 <strong>聊天</strong> 打个招呼。收到回复就说明模型链路是通的。</p><h2 id="使用自己的模型-byok" tabindex="-1">使用自己的模型（BYOK） <a class="header-anchor" href="#使用自己的模型-byok" aria-label="Permalink to &quot;使用自己的模型（BYOK）&quot;">​</a></h2><p>托管模型之外，你随时可以自带模型（Bring Your Own Key）：</p><ol><li>在侧边栏打开 <strong>模型服务商</strong>，点击 <strong>添加服务商</strong>。</li><li>选择模板（OpenAI、Anthropic、Gemini、DeepSeek、智谱、OpenRouter、Ollama 等），填入你的 API Key；OpenAI 兼容端点再补上对应的 Base URL。</li><li>打开该服务商并<strong>同步</strong>模型列表，或手动添加至少一个对话模型，然后在 Bot 的 <strong>通用</strong> 标签页切换过去。</li></ol><p>BYOK 的模型用量按你所选服务商的价格计费。编码智能体同理：在 Bot 的 <strong>Agent</strong> 标签页，用你自己的订阅或 API Key 登录 Claude Code、Codex。各家的字段与注意事项见 <a href="./../integrations/providers/llm.html">模型服务商</a>。</p><h2 id="第-4-步-交给它第一个任务" tabindex="-1">第 4 步：交给它第一个任务 <a class="header-anchor" href="#第-4-步-交给它第一个任务" aria-label="Permalink to &quot;第 4 步：交给它第一个任务&quot;">​</a></h2><p>一个好的首次请求会回答五个问题：</p><table tabindex="0"><thead><tr><th>要素</th><th>它回答的问题</th></tr></thead><tbody><tr><td><strong>结果</strong></td><td>做完之后应该存在什么？</td></tr><tr><td><strong>来源</strong></td><td>涉及哪些文件、网站或对话？</td></tr><tr><td><strong>约束</strong></td><td>什么不能碰，什么需要你批准？</td></tr><tr><td><strong>形式</strong></td><td>结果以什么形式交付？</td></tr><tr><td><strong>确认点</strong></td><td>什么时候该停下来跟你确认？</td></tr></tbody></table><p>想在几分钟内看到结果、又不需要任何外部登录，可以上传一份文档试试：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把这份文档总结成五个要点。另起一节，列出其中所有的日期、决定和待解决问题，</span></span>
<span class="line"><span>并标注每条来自哪一页或哪一节。不要修改原文件。</span></span></code></pre></div><p>Bot 会在自己的工作区里读取文件，并把结果写回对话。它产出的一切都留在工作区，你可以在 <a href="./files.html">文件</a> 里浏览和编辑。</p><h2 id="第-5-步-让它用上工作区和浏览器" tabindex="-1">第 5 步：让它用上工作区和浏览器 <a class="header-anchor" href="#第-5-步-让它用上工作区和浏览器" aria-label="Permalink to &quot;第 5 步：让它用上工作区和浏览器&quot;">​</a></h2><p>工作区是 Bot 干活的地方。它有 Linux 文件系统、终端和预装工具链（Python、Node.js、uv、npm），数据清洗、脚本、构建都能直接跑：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把我刚上传的 CSV 里 email 列为空的行全部删掉。</span></span>
<span class="line"><span>给我清洗后的文件，并告诉我删了多少行。</span></span></code></pre></div><p>当任务需要真实浏览器时——比如无头模式下会出错的站点，或需要登录才能访问的页面——在 Bot 的 <strong>桌面</strong> 标签页启用可视化桌面。启动后，Bot 会驱动一个有头 Chrome，你可以在桌面面板里看着它操作。</p><p>遇到登录墙时，你可以自己接管屏幕：输入密码、通行密钥或一次性验证码，然后把控制权交还给它。浏览器会话保留在该工作区中，后续任务依然是登录状态。</p><div class="warning custom-block"><p class="custom-block-title">按需授权</p><p>工作区权限是分级的：仅聊天、读文件、写文件、执行命令、管理容器。任务需要哪一级就给哪一级，不要多给。参见 <a href="./access.html">访问控制</a>。</p></div><p>详见 <a href="./container.html">工作区</a> 与 <a href="./browser-computer-use.html">浏览器 / 电脑操作</a>。</p><h2 id="第-6-步-在聊天平台上找到它" tabindex="-1">第 6 步：在聊天平台上找到它 <a class="header-anchor" href="#第-6-步-在聊天平台上找到它" aria-label="Permalink to &quot;第 6 步：在聊天平台上找到它&quot;">​</a></h2><p>Bot 在你本来就聊天的地方最有用。</p><ol><li>打开 Bot 的 <strong>平台</strong> 标签页，点击 <strong>添加</strong>。</li><li>选择平台——Telegram、Slack、Discord、飞书、钉钉、企业微信、微信、QQ 或 LINE——并填入该平台的凭据。</li><li>从该平台给它发消息。第一条消息会创建会话；发送 <code>/help</code> 可以看到可用的 <a href="./slash-commands.html">斜杠命令</a>。</li></ol><p>从此你可以在手机上派活，然后在同一个对话里收结果。各平台的具体配置见 <a href="./../integrations/channels/">渠道</a>。</p><h2 id="第-7-步-复盘-然后固化下来" tabindex="-1">第 7 步：复盘，然后固化下来 <a class="header-anchor" href="#第-7-步-复盘-然后固化下来" aria-label="Permalink to &quot;第 7 步：复盘，然后固化下来&quot;">​</a></h2><p>有问题就直接说。把纠正写成长期规则，而不是一次性修补：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以后所有的摘要都用这个格式：按主题分组，每篇一行，链接放在行内，</span></span>
<span class="line"><span>最后加一节&quot;值得再读&quot;。</span></span></code></pre></div><p>当一套流程稳定下来后，就别再重复输入了：</p><ul><li>存成 <a href="./skills.html">技能</a>，以后一句话唤起整套流程。</li><li>变成 <a href="./schedule.html">定时任务</a>，按 cron 自动运行，完全不需要聊天。</li><li>用 <a href="./memory.html">长期记忆</a> 把你的偏好和项目上下文带进之后的每一次会话。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>阅读</th></tr></thead><tbody><tr><td>逐个标签页配置 Bot</td><td><a href="./working-with-bots.html">Bot</a></td></tr><tr><td>理解聊天、讨论与消息路由</td><td><a href="./sessions.html">会话</a></td></tr><tr><td>运行定时或周期任务</td><td><a href="./schedule.html">定时任务</a></td></tr><tr><td>接入外部工具和数据</td><td><a href="./mcp.html">MCP</a>、<a href="./connectors.html">连接器</a></td></tr><tr><td>安装现成的能力</td><td><a href="./supermarket.html">应用市场</a></td></tr><tr><td>在生命周期节点挂自己的逻辑</td><td><a href="./hooks.html">钩子</a></td></tr><tr><td>控制谁能跟 Bot 说话</td><td><a href="./access.html">访问控制</a></td></tr><tr><td>看看别人怎么用</td><td><a href="./use-cases.html">使用场景</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">需要帮助？</p><p>订阅、credits 或账号相关的问题，以及本文档没有覆盖的疑问，都可以在 <a href="https://memoh.ai/help" target="_blank" rel="noreferrer">帮助中心</a> 找到答案，也可以从那里联系 Memoh 团队。</p></div>`,44)])])}const u=a(s,[["render",n]]);export{m as __pageData,u as default};
